import{_ as i,o as l,c as e,a3 as r}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"庄子导读","description":"从内篇、外篇、杂篇三层结构进入庄子的寓言与思想世界。","frontmatter":{"title":"庄子导读","description":"从内篇、外篇、杂篇三层结构进入庄子的寓言与思想世界。"},"headers":[],"relativePath":"daoism/zhuang-zi/index.md","filePath":"daoism/zhuang-zi/index.md","lastUpdated":1789987057000}'),h={name:"daoism/zhuang-zi/index.md"};function o(t,a,n,d,s,u){return l(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="庄子导读" tabindex="-1">庄子导读 <a class="header-anchor" href="#庄子导读" aria-label="Permalink to &quot;庄子导读&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>《庄子》不是对《道德经》的简单重复，而是把“道”的问题推进到更宽阔的人生、语言、政治、技艺与生死经验之中。</p><p>它既有极高的思想密度，也有极强的文学性。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li>它让“道”从简短格言变成丰富生命经验</li><li>它通过寓言、人物与辩难，让读者进入更活的理解</li><li>它能帮助读者从“概念理解”走向“视野转换”</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ul><li>不求一口气通读全书</li><li>先分清内篇、外篇、杂篇</li><li>可先按篇章标题建立目录感，再逐步进入原文</li><li>解读可后补，先把原典入口与骨架立住</li></ul><h2 id="篇章" tabindex="-1">篇章 <a class="header-anchor" href="#篇章" aria-label="Permalink to &quot;篇章&quot;">​</a></h2><p>当前先把 33 篇的篇名与路径立住，已整理的附上原文链接，其余按顺序推进。</p><p>当前先把 33 篇的篇名与路径立住，已整理的附上原文链接，其余按顺序推进。</p><h3 id="内篇" tabindex="-1">内篇 <a class="header-anchor" href="#内篇" aria-label="Permalink to &quot;内篇&quot;">​</a></h3><ul><li><a href="/Dao/daoism/zhuang-zi/chapter-01">逍遥游</a></li><li><a href="/Dao/daoism/zhuang-zi/chapter-02">齐物论</a></li><li><a href="/Dao/daoism/zhuang-zi/chapter-03">养生主</a></li><li><a href="/Dao/daoism/zhuang-zi/chapter-04">人间世</a></li><li><a href="/Dao/daoism/zhuang-zi/chapter-05">德充符</a></li><li><a href="/Dao/daoism/zhuang-zi/chapter-06">大宗师</a></li><li><a href="/Dao/daoism/zhuang-zi/chapter-07">应帝王</a></li></ul><h3 id="外篇" tabindex="-1">外篇 <a class="header-anchor" href="#外篇" aria-label="Permalink to &quot;外篇&quot;">​</a></h3><ul><li><a href="/Dao/daoism/zhuang-zi/chapter-08">骈拇</a></li><li><a href="/Dao/daoism/zhuang-zi/chapter-09">马蹄</a></li><li><a href="/Dao/daoism/zhuang-zi/chapter-10">胠箧</a></li><li><a href="/Dao/daoism/zhuang-zi/chapter-11">在宥</a></li><li><a href="/Dao/daoism/zhuang-zi/chapter-12">天地</a></li><li><a href="/Dao/daoism/zhuang-zi/chapter-13">天道</a></li><li><a href="/Dao/daoism/zhuang-zi/chapter-14">天运</a></li><li>刻意（待整理）</li><li>缮性（待整理）</li><li>秋水（待整理）</li><li>至乐（待整理）</li><li>达生（待整理）</li><li>山木（待整理）</li><li>田子方（待整理）</li><li>知北游（待整理）</li></ul><h3 id="杂篇" tabindex="-1">杂篇 <a class="header-anchor" href="#杂篇" aria-label="Permalink to &quot;杂篇&quot;">​</a></h3><ul><li>庚桑楚（待整理）</li><li>徐无鬼（待整理）</li><li>则阳（待整理）</li><li>外物（待整理）</li><li>寓言（待整理）</li><li>让王（待整理）</li><li>盗跖（待整理）</li><li>说剑（待整理）</li><li>渔父（待整理）</li><li>列御寇（待整理）</li><li>天下（待整理）</li></ul><h2 id="当前整理进度" tabindex="-1">当前整理进度 <a class="header-anchor" href="#当前整理进度" aria-label="Permalink to &quot;当前整理进度&quot;">​</a></h2><ul><li>内篇七篇已按「原文 · 引读 · 字词释义 · 三问解读」整理为首版阅读页</li><li>外篇、杂篇的篇名、分组与路径已立，原文与释义后续分批导入</li><li>解读层未完成处统一保留「待整理」标记</li></ul>',19)])])}const p=i(h,[["render",o]]);export{m as __pageData,p as default};
